WITH exploded AS (SELECT id, created_at, EXPLODE_OUTER(coupon_codes) AS element FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, element, COUNT_IF(element = 'WELCOME5') AS welcome5_events, SIZE(COLLECT_SET(element)) AS num_elements, COUNT(*) AS event_count, SIZE(COLLECT_SET(element)) AS num_elements_2, MAX(created_at) AS last_seen, MAX(created_at) AS ended_at FROM exploded GROUP BY DATE_TRUNC('DAY', created_at), element;
